 if(results[i].status==="fulfilled"){image(results[i].value.image_url,"original");}
 else text(results[i]);
}
store("viewResults",results.map((r,i)=>({view:views[i].id,status:r.status,detail:r.value?.detail})));

const notes=[
"Native transparent candidate: one antenna at image right and one yellow eye at image left are visible; the second antenna and eye are absent.",
"Native candidate on white: silhouette has only the image-right antenna; only the image-left yellow eye is present.",
"8x nearest candidate on white: top-left antenna is missing above the flat head edge; the position of the reference's image-right yellow eye is filled with cyan. The image-right antenna and image-left yellow eye remain.",
"Native candidate on dark: one antenna and one yellow eye remain; the dark outline has lower background contrast, but the paired identity features are absent.",
"8x nearest candidate on dark: confirms no image-left antenna and no image-right yellow eye; pixel edges remain hard.",
"Native transparent reference: two separated upper antennae and two yellow eyes are visible.",
"Native reference on white: both image-left and image-right antennae and both yellow eyes read as pairs.",
"8x nearest reference on white: two dark vertical antennae project above the head, and two separated yellow rectangular eyes sit within the cyan face; comparison identifies the candidate's missing left antenna and right eye.",
"Native reference on dark: both antennae and both yellow eyes remain visible, with reduced dark-outline contrast against this background.",
"8x nearest reference on dark: paired antennae and paired yellow eye clusters are confirmed against the same background used for the candidate."
];
const packet=load("packet");
const observation={
 reviewer:"actor",
 observed_at:load("observedAt"),
 observations:packet.views.map((v,i)=>({view:v.id,delivered_size:[v.width,v.height],note:notes[i]+" Opened through the host view_image tool with original detail; delivered without resizing."})),
 verdicts:[
 {criterion:"q.mechanical",status:"pass",reason:"The saved check text and contract require 32x32, only #25354A, #56B5BC and #F4DDA2, and binary alpha. Retained candidate measurements show one 32x32 frame, 3 visible colors, 0 outside-palette colors, 0 fractional-alpha pixels and no mechanical failures. The criterion display name says 2 by 2, but its explicit check, confirmed dimensions, contract and brief all specify 32x32; requirements are retained unchanged.",supersedes:null},
 {criterion:"q.visual",status:"fail",reason:"Actual host inspection of all retained candidate and reference views at native size and 8x nearest enlargement on white and dark backgrounds shows that the reference has two antennae and two yellow eyes. The candidate lacks the image-left antenna and image-right yellow eye; only the image-right antenna and image-left yellow eye remain. It therefore fails the saved requirement to preserve both antennae and both yellow eyes, despite passing mechanical constraints.",supersedes:null},
 {criterion:"q.engine",status:"unavailable",reason:"No target browser project is available, so actual import and nearest-sampling behavior cannot be executed or verified. Local raster measurements and host image viewing do not satisfy the required live browser check.",supersedes:null}
 ],
 next_action:"Preserve rejected candidate X candidate and candidate.png unchanged. A future authorized art revision must be a separate candidate, proposed ID candidate.revision.1, for saved output output; it must restore the image-left antenna and image-right yellow eye to match reference.png while preserving 32x32, the declared palette and binary alpha. No revision art or candidate record is created in this review-only task. Prepare a fresh inspection packet for that new candidate and evaluate every saved criterion independently; it inherits no verdicts. Keep task open. When the target browser project is supplied, execute import and nearest-sampling checks and retain actual live evidence before acceptance. No remote provider is available, and no generation or dispatch was attempted.",
 limitations:[
 "This review covers the supplied static frame and all ten retained native and 8x views; it does not establish target-browser import behavior.",
 "The browser import and nearest-sampling criterion remains unavailable because no target project exists in this session.",
 "No remote provider is available; no art was edited or generated. The separate revision is a retained next action only.",
 "The saved q.mechanical display name says 2 by 2, while its check text, contract, confirmed intake and brief consistently require 32x32. Evaluation uses those explicit requirements; original records were not amended."
 ]
};
